4	use axum::middleware::Next;
5	use axum::response::Response;
6	use uuid::Uuid;
7	
8	const X_REQUEST_ID: HeaderName = HeaderName::from_static("x-request-id");
9	
10	/// Echo the request's `X-Request-Id` on the response, or generate a fresh
11	/// `uuid4` hex if the request did not provide one.
12	///
13	/// Original Python:
14	/// `vllm.entrypoints.openai.server_utils.XRequestIdMiddleware`.
15	pub async fn set_request_id_header(req: Request, next: Next) -> Response {
16	    let incoming = req.headers().get(&X_REQUEST_ID).cloned();
17	    let mut response = next.run(req).await;
18	    let value = incoming.unwrap_or_else(|| {
19	        HeaderValue::from_str(&Uuid::new_v4().simple().to_string())
20	            .expect("uuid hex is valid header value")
21	    });
22	    response.headers_mut().insert(X_REQUEST_ID, value);
23	    response
24	}
