39	/// Track frontend-local in-flight inference requests for the `/load` endpoint.
40	pub async fn track_server_load(
41	    State(state): State<Arc<AppState>>,
42	    req: Request,
43	    next: Next,
44	) -> Response {
45	    let handler = req
46	        .extensions()
47	        .get::<MatchedPath>()
48	        .map_or_else(|| "none", |path| path.as_str());
49	
50	    if !TRACKED_HANDLERS.contains(&handler) {
51	        return next.run(req).await;
52	    }
53	
54	    state.increment_server_load();
55	    let guard = ServerLoadGuard {
56	        state: Arc::downgrade(&state),
57	    };
