use axum::Json;
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::state::AppState;

/// Route prefixes that require a valid API key when authentication is enabled.
const GUARDED_PREFIXES: &[&str] = &["/v1", "/v2", "/inference"];

/// Enforce bearer-token authentication for guarded inference and model-listing
/// routes.
///
/// Requests to guarded prefixes must carry an `Authorization: Bearer <key>`
/// header whose key matches one of the configured API keys. `OPTIONS` requests
/// (CORS preflight) and any route outside the guarded prefixes (for example
/// `/health`) are always allowed through. When no API keys are configured this
/// middleware is a no-op.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    let api_keys = state.api_keys();

    // Authentication disabled: no keys configured.
    if api_keys.is_empty() {
        return next.run(req).await;
    }

    // Allow CORS preflight requests without credentials.
    if req.method() == Method::OPTIONS {
        return next.run(req).await;
    }

    // Only guarded prefixes require authentication.
    if !is_guarded_path(req.uri().path()) {
        return next.run(req).await;
    }

    if is_authorized(&req, api_keys) {
        next.run(req).await
    } else {
        unauthorized()
    }
}

/// Whether `path` falls under one of the guarded route prefixes.
///
/// A prefix matches the exact path or any path immediately followed by `/`, so
/// `/v1` guards `/v1` and `/v1/models` but not an unrelated `/v1beta`.
fn is_guarded_path(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| {
        path.strip_prefix(prefix)
            .is_some_and(|rest| rest.is_empty() || rest.starts_with('/'))
    })
}

/// Whether the request carries an `Authorization: Bearer <key>` header matching
/// one of the accepted API keys.
fn is_authorized(req: &Request, api_keys: &[String]) -> bool {
    let Some(value) = req.headers().get(header::AUTHORIZATION) else {
        return false;
    };
    let Ok(value) = value.to_str() else {
        return false;
    };
    let Some(token) = value.strip_prefix("Bearer ") else {
        return false;
    };
    api_keys.iter().any(|key| key == token)
}

/// Build the `401 Unauthorized` response returned for rejected requests.
fn unauthorized() -> Response {
    (StatusCode::UNAUTHORIZED, Json(json!({ "error": "Unauthorized" }))).into_response()
}
